NEW_HTML = """<ul>
  <li class="new">Suç ve Ceza | Dostoyevski | 111</li>
  <li class="old">Eski Kitap | Biri | 999</li>
  <li class="new">Simyacı | Coelho | 222</li>
  <li class="new"> 1984 |Orwell| 333 </li>
</ul>"""

