    def __init__(self, isbn, title, author):
        self.isbn = isbn
        self.title = title
        self.author = author
        self.available = True

    def borrow(self):
        if not self.available:
            return False
        self.available = False
        return True

    def give_back(self):
        self.available = True

    def __str__(self):
        status = "rafta" if self.available else "ödünçte"
        return f"{self.title} - {self.author} ({status})"

class ReferenceBook(Book):
    def borrow(self):
        return False


class Library:
    def __init__(self, loan_limit=2):
        self.books = {}
        self.loans = {}
        self.loan_limit = loan_limit

    def add_book(self, book):
        self.books[book.isbn] = book

    def checkout(self, member, isbn):
        book = self.books.get(isbn)
        if book is None:
            return False
        borrowed = self.loans.get(member, [])
        if len(borrowed) >= self.loan_limit or not book.borrow():
            return False
        self.loans[member] = borrowed + [isbn]
        return True

    def return_book(self, member, isbn):
        borrowed = self.loans.get(member, [])
        if isbn not in borrowed:
            return False
        self.books[isbn].give_back()
        borrowed.remove(isbn)
        return True

